#
# Conan 2 compatibility plugin, installed into the project-scoped Conan home by
# cmake/fetch_conan.cmake. Derived from the plugin Conan 2.31 generates by
# default: cppstd_compat() and _factors_combinations() are unchanged, the MSVC
# fallback map is extended.
#
# Do NOT re-add the "This file was generated by Conan" header from the stock
# plugin - Conan overwrites any file that still carries it.
#
# Re-sync with the stock plugin if a Conan upgrade changes the plugin API.

from conan.tools.build import supported_cppstd, supported_cstd


def cppstd_compat(conanfile):
    # It will try to find packages with all the cppstd versions
    extension_properties = getattr(conanfile, "extension_properties", {})
    compiler = conanfile.settings.get_safe("compiler")
    compiler_version = conanfile.settings.get_safe("compiler.version")
    cppstd = conanfile.settings.get_safe("compiler.cppstd")
    if not compiler or not compiler_version:
        return []
    factors = []  # List of list, each sublist is a potential combination
    if cppstd is not None and extension_properties.get("compatibility_cppstd") is not False:
        cppstd_possible_values = supported_cppstd(conanfile)
        if cppstd_possible_values is None:
            conanfile.output.warning(f'No cppstd compatibility defined for compiler "{compiler}"')
        else:  # The current cppstd must be included in case there is other factor
            factors.append([{"compiler.cppstd": v} for v in cppstd_possible_values])

    cstd = conanfile.settings.get_safe("compiler.cstd")
    if cstd is not None and extension_properties.get("compatibility_cstd") is not False:
        cstd_possible_values = supported_cstd(conanfile)
        if cstd_possible_values is None:
            conanfile.output.warning(f'No cstd compatibility defined for compiler "{compiler}"')
        else:
            factors.append([{"compiler.cstd": v} for v in cstd_possible_values if v != cstd])
    return factors


# MSVC keeps binary compatibility across toolset updates, so a build with a newer
# compiler can consume packages produced by an older one. ConanCenter publishes
# msvc 194 binaries only, while Visual Studio 2026 detects as msvc 195: without
# this fallback every dependency is rebuilt from source, which takes about an
# hour. Deliberately limited to the v143 family rather than "every older
# version", so the set of binaries Conan may pick stays predictable.
#
# Note that the reverse - declaring compiler.version=194 in the profile - is not
# a workaround: Conan derives vcvars_ver from compiler.version, so it would call
# vcvarsall.bat with -vcvars_ver=14.4, which fails on a machine that only has the
# 14.5 toolset installed.
MSVC_FALLBACKS = {
    "195": ["194", "193"],
    "194": ["193"],
}


def compatibility(conanfile):
    # By default, different compiler.cppstd are compatible
    # factors is a list of lists
    factors = cppstd_compat(conanfile)

    compiler = conanfile.settings.get_safe("compiler")
    compiler_version = conanfile.settings.get_safe("compiler.version")
    if compiler == "msvc":
        msvc_fallbacks = MSVC_FALLBACKS.get(compiler_version)
        if msvc_fallbacks:
            factors.append([{"compiler.version": v} for v in msvc_fallbacks])

    # Combine factors to compute all possible configurations
    combinations = _factors_combinations(factors)
    # Final compatibility settings combinations to check
    return [{"settings": [(k, v) for k, v in comb.items()]} for comb in combinations]


def _factors_combinations(factors):
    combinations = []
    for factor in factors:
        if not combinations:
            combinations = factor
            continue
        new_combinations = []
        for comb in combinations:
            for f in factor:
                new_comb = comb.copy()
                new_comb.update(f)
                new_combinations.append(new_comb)
        combinations.extend(new_combinations)
    return combinations
